import React, { useEffect, useState } from "react";

export default function UserHistory({ onCancel }) {
  const [combinedHistory, setCombinedHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    setLoading(true);
    setMessage("");

    try {
      const [withdrawRes, depositRes] = await Promise.all([
        fetch("http://localhost:8080/api/withdraw/history", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
        fetch("http://localhost:8080/api/deposit/my-history", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
      ]);

      if (!withdrawRes.ok || !depositRes.ok) {
        throw new Error("ডেটা লোড করা যায়নি");
      }

      const [withdrawData, depositData] = await Promise.all([
        withdrawRes.json(),
        depositRes.json(),
      ]);

      const formatStatus = (status) =>
        status === "APPROVED" ? "COMPLETED" : status;

      const formattedWithdraws = withdrawData.map((item) => ({
        ...item,
        type: "Withdraw",
        date: item.requestedAt,
        number: item.receiverNumber,
        status: formatStatus(item.status),
      }));

      const formattedDeposits = depositData.map((item) => ({
        ...item,
        type: "Deposit",
        date: item.requestedAt,
        number: item.senderNumber,
        status: formatStatus(item.status),
      }));

      const combined = [...formattedWithdraws, ...formattedDeposits].sort(
        (a, b) => new Date(b.date) - new Date(a.date)
      );

      setCombinedHistory(combined);
    } catch (err) {
      console.error(err);
      setMessage("হিস্টোরি লোড করা যায়নি।");
    } finally {
      setLoading(false);
    }
  };

  const statusColor = {
    PENDING: "bg-yellow-500",
    REJECTED: "bg-red-600",
    COMPLETED: "bg-blue-600",
  };

  return (
    <div className="max-w-7xl mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
          📜 আমার ট্রানজেকশন হিস্টোরি
        </h2>
        <button
          onClick={onCancel}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-md"
        >
          ← ফিরে যান
        </button>
      </div>

      {loading ? (
        <p className="text-center text-gray-500">লোড হচ্ছে...</p>
      ) : message ? (
        <p className="text-center text-red-600 font-semibold">{message}</p>
      ) : combinedHistory.length === 0 ? (
        <p className="text-center text-gray-500">কোনো হিস্টোরি পাওয়া যায়নি।</p>
      ) : (
        <div className="overflow-x-auto bg-white dark:bg-gray-900 border rounded-xl shadow">
          <table className="min-w-full text-sm text-left divide-y divide-gray-200 dark:divide-gray-700">
            <thead className="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200 text-xs font-semibold">
              <tr>
                <th className="px-4 py-3">ID</th>
                <th className="px-4 py-3">টাইপ</th>
                <th className="px-4 py-3">ট্রানজেকশন আইডি</th>
                <th className="px-4 py-3">পেমেন্ট পদ্ধতি</th>
                <th className="px-4 py-3">নম্বর</th>
                <th className="px-4 py-3">অ্যামাউন্ট</th>
                <th className="px-4 py-3">স্ট্যাটাস</th>
                <th className="px-4 py-3">তারিখ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-gray-800 dark:text-gray-100">
              {combinedHistory.map((item) => (
                <tr key={`${item.type}-${item.id}`} className="hover:bg-gray-50 dark:hover:bg-gray-800">
                  <td className="px-4 py-2">{item.id}</td>
                  <td className="px-4 py-2">
                    {item.type === "Deposit" ? "💰 Deposit" : "🧾 Withdraw"}
                  </td>
                  <td className="px-4 py-2">{item.transactionId}</td>
                  <td className="px-4 py-2">{item.method}</td>
                  <td className="px-4 py-2">{item.number}</td>
                  <td className="px-4 py-2 font-semibold text-gray-900 dark:text-white">
                    ৳ {Number(item.amount).toFixed(2)}
                  </td>
                  <td className="px-4 py-2">
                    <span
                      className={`px-2 py-1 text-xs font-semibold text-white rounded ${statusColor[item.status] || "bg-gray-500"}`}
                    >
                      {item.status}
                    </span>
                  </td>
                  <td className="px-4 py-2">{new Date(item.date).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
